     1	import { claim } from "./claim.js";
     2	import type { Damage } from "./damage-report.js";
     3	import type { Customer, Item } from "./policy.js";
     4	import { payoutCap } from "./policy-cover.js";
     5	import { quote } from "./quote.js";
     6	
     7	/**
     8	 * A scenario arrives as JSON, so a step's `op` is read as the string it was
     9	 * written as rather than as a narrowed literal type. Narrowing it is the
    10	 * CLI's job, at the boundary where an unrecognised step is refused with a
    11	 * non-zero exit.
    12	 */
    13	export interface QuoteStep {
    14	  readonly op: string;
    15	  readonly items: readonly Item[];
    16	}
    17	
    18	export interface Incident {
    19	  readonly cause: string;
    20	  readonly damages: readonly Damage[];
    21	}
    22	
    23	/** A claim names the policy an earlier quote step created, by its index. */
    24	export interface ClaimStep {
    25	  readonly op: string;
    26	  readonly policy: number;
    27	  readonly incident: Incident;
    28	}
    29	
    30	export type Step = QuoteStep | ClaimStep;
    31	
    32	export interface Scenario {
    33	  readonly customer: Customer;
    34	  readonly steps: readonly Step[];
    35	}
    36	
    37	export interface QuoteResult {
    38	  readonly premium: number;
    39	}
    40	
    41	/**
    42	 * What a claim step writes out. These field names are the MHPCO's published
    43	 * output schema, which is why the shape is stated here rather than reusing
    44	 * the settlement's own result: a settlement result is what the claim rules
    45	 * computed, this is what the CLI publishes, and the MHPCO can revise the
    46	 * wire format and the calculation on their own schedules. Today the two
    47	 * coincide exactly, and stating them apart is what keeps that a fact rather
    48	 * than an assumption.
    49	 */
    50	export interface ClaimStepResult {
    51	  readonly payout: number;
    52	  readonly remainingCap: number;
    53	}
    54	
    55	export type StepResult = QuoteResult | ClaimStepResult;
    56	
    57	export interface ScenarioResults {
    58	  readonly results: readonly StepResult[];
    59	}
    60	
    61	const CLAIM_OP = "claim";
    62	
    63	/**
    64	 * Which operation a step asks for. Because `op` is the raw string JSON
    65	 * carried, this recognises a claim rather than proving one: a step whose
    66	 * `op` is neither operation is not refused here but at the CLI boundary,
    67	 * which is where an unrecognised scenario earns its non-zero exit. Within a
    68	 * scenario that boundary has already vouched for the steps, so anything not
    69	 * asking for a claim is quoted.
    70	 */
    71	function isClaimStep(step: Step): step is ClaimStep {
    72	  return step.op === CLAIM_OP;
    73	}
    74	
    75	/**
    76	 * A policy, as a scenario knows it: the items a quote step covered and the
    77	 * cap those items still allow after the claims settled against it so far.
    78	 */
    79	interface Policy {
    80	  readonly items: readonly Item[];
    81	  remainingCap: number;
    82	}
    83	
    84	/**
    85	 * The policies a scenario has opened, and what each of them can still pay
    86	 * out.
    87	 *
    88	 * How a policy is addressed and how its cap carries across successive claims
    89	 * are one piece of knowledge, held here: a claim names the policy by the
    90	 * zero-based index of the quote step that opened it, and each settlement
    91	 * draws that policy's own cap down for the next one. The MHPCO could revise
    92	 * either -- address policies by a number of their own, let a claim settle
    93	 * against the latest policy -- without touching what a quote costs or what a
    94	 * claim pays, which is why the register is stated apart from both.
    95	 */
    96	class PolicyRegister {
    97	  private readonly policies = new Map<number, Policy>();
    98	
    99	  /** A quote step opens a policy at its own step index, with a full cap. */
   100	  open(stepIndex: number, items: readonly Item[]): void {
   101	    this.policies.set(stepIndex, {
   102	      items,
   103	      remainingCap: payoutCap(items),
   104	    });
   105	  }
   106	
   107	  /**
   108	   * Settling an incident against the policy a claim names, drawing that
   109	   * policy's cap down by what it pays out.
   110	   */
   111	  settle(stepIndex: number, damages: readonly Damage[]): ClaimStepResult {
   112	    const policy = this.policyOpenedBy(stepIndex);
   113	    const settled = claim(policy.items, damages, policy.remainingCap);
   114	    policy.remainingCap = settled.remainingCap;
   115	    return settled;
   116	  }
   117	
   118	  private policyOpenedBy(stepIndex: number): Policy {
   119	    const policy = this.policies.get(stepIndex);
   120	    if (policy === undefined) {
   121	      throw new Error(
   122	        `Step ${stepIndex} did not create a policy to claim against`,
   123	      );
   124	    }
   125	    return policy;
   126	  }
   127	}
   128	
   129	/**
   130	 * The steps of a scenario are processed in order for one customer, each
   131	 * contributing one result in its own position.
   132	 *
   133	 * A quote is a contract taken out, so it is quoting -- not merely reaching
   134	 * the next step -- that advances the contract count the follow-up contract
   135	 * discount reads. A claim settles against the policy an earlier quote
   136	 * created and draws down that policy's own cap.
   137	 */
   138	export function runScenario(scenario: Scenario): ScenarioResults {
   139	  const results: StepResult[] = [];
   140	  const policies = new PolicyRegister();
   141	  let contractsTakenOut = 0;
   142	
   143	  scenario.steps.forEach((step, stepIndex) => {
   144	    if (isClaimStep(step)) {
   145	      results.push(policies.settle(step.policy, step.incident.damages));
   146	      return;
   147	    }
   148	    policies.open(stepIndex, step.items);
   149	    results.push({
   150	      premium: quote(scenario.customer, step.items, contractsTakenOut),
   151	    });
   152	    contractsTakenOut += 1;
   153	  });
   154	
   155	  return { results };
   156	}
