     1	import type { Damage } from "./damage-report.js";
     2	import { reportedDamageAmount } from "./damage-report.js";
     3	import { damagedItems } from "./damaged-item.js";
     4	import type { Item } from "./policy.js";
     5	import { payoutRoundedInMHPCOsFavour } from "./rounding.js";
     6	import { reimbursementRateOf } from "./reimbursement-clause.js";
     7	
     8	export interface ClaimResult {
     9	  readonly payout: number;
    10	  readonly remainingCap: number;
    11	}
    12	
    13	/**
    14	 * The policyholder bears a deductible on each damaged item, so an incident
    15	 * that damages several items bears it several times -- once per damage
    16	 * entry, which is why the payout is accumulated per entry rather than off
    17	 * the incident's total.
    18	 */
    19	const DEDUCTIBLE = 100;
    20	
    21	/**
    22	 * A payout is money the MHPCO pays out, so it floors at nothing: the
    23	 * deductible can reduce a payout to zero, but a damage smaller than the
    24	 * deductible never turns into a debt owed to the MHPCO.
    25	 */
    26	const NOTHING_PAID_OUT = 0;
    27	
    28	/** What one damage settles at: the reimbursed share, less the deductible. */
    29	function payoutForDamage(damagedItem: Item, damage: Damage): number {
    30	  const reimbursed =
    31	    reportedDamageAmount(damage) * reimbursementRateOf(damagedItem);
    32	  return Math.max(reimbursed - DEDUCTIBLE, NOTHING_PAID_OUT);
    33	}
    34	
    35	/**
    36	 * What an incident settles at: each damage entry is settled on its own --
    37	 * under the clauses of the item it hit, and bearing its own deductible --
    38	 * and the entries accumulate. An incident that damages nothing settles at
    39	 * nothing.
    40	 */
    41	function incidentPayout(
    42	  items: readonly Item[],
    43	  damages: readonly Damage[],
    44	): number {
    45	  const hit = damagedItems(
    46	    items,
    47	    damages.map((damage) => damage.itemType),
    48	  );
    49	  return damages.reduce(
    50	    (total, damage, entry) => total + payoutForDamage(hit[entry], damage),
    51	    NOTHING_PAID_OUT,
    52	  );
    53	}
    54	
    55	/** What a draw against the cap takes, and what it leaves behind. */
    56	interface CapDraw {
    57	  readonly drawn: number;
    58	  readonly remainingCap: number;
    59	}
    60	
    61	/**
    62	 * The policy pays no more than its cap still allows, so a payout the cap
    63	 * cannot cover is reduced to what is left of it -- and once the cap is
    64	 * exhausted it draws nothing at all.
    65	 *
    66	 * What a draw takes and what it leaves are one fact about the cap, stated
    67	 * here together so that neither can be revised without the other.
    68	 *
    69	 * The cap is a separate limit from the clauses and the deductible: those
    70	 * decide what the MHPCO owes for a damage, whereas the cap decides how much
    71	 * a policy can still pay out at all, and the MHPCO revises the two on their
    72	 * own schedules -- which is why drawing against the cap is stated apart from
    73	 * what a damage settles at.
    74	 */
    75	function drawAgainstCap(capBeforeClaim: number, desiredPayout: number): CapDraw {
    76	  const drawn = Math.min(desiredPayout, capBeforeClaim);
    77	  return { drawn, remainingCap: capBeforeClaim - drawn };
    78	}
    79	
    80	/**
    81	 * What the incident settles at as a final payout: whole G, rounded in the
    82	 * MHPCO's favour.
    83	 *
    84	 * The rounding happens here, before the cap is drawn against, rather than on
    85	 * whatever the draw yields. The clauses and the deductible are the
    86	 * calculation, and its result is the final payout the spec has rounded; the
    87	 * cap is a limit applied to that finished amount, not a further step of the
    88	 * calculation. Rounding first is also what keeps the cap's ledger honest:
    89	 * the policy is debited exactly the whole G it pays out, so the payout and
    90	 * the remaining cap always add back up to the cap before the claim.
    91	 *
    92	 * Under the present rules the alternative ordering is indistinguishable --
    93	 * a cap is always whole G, so a draw that binds yields that same whole
    94	 * number either way -- which is precisely why the choice is stated here by
    95	 * name instead of being left implicit in the order of two calls.
    96	 */
    97	function finalPayoutFor(
    98	  items: readonly Item[],
    99	  damages: readonly Damage[],
   100	): number {
   101	  return payoutRoundedInMHPCOsFavour(incidentPayout(items, damages));
   102	}
   103	
   104	/**
   105	 * Settling an incident against the policy that covers it: what the incident
   106	 * settles at, and what it leaves of the policy's cap.
   107	 */
   108	export function claim(
   109	  items: readonly Item[],
   110	  damages: readonly Damage[],
   111	  capBeforeClaim: number,
   112	): ClaimResult {
   113	  const { drawn, remainingCap } = drawAgainstCap(
   114	    capBeforeClaim,
   115	    finalPayoutFor(items, damages),
   116	  );
   117	  return { payout: drawn, remainingCap };
   118	}
